function tmlParseDate(s){
  var m=/^(\d{4})(?:-(\d{1,2}))?(?:-(\d{1,2}))?$/.exec(String(s||'').trim());
  if(!m) return null;
  var y=Number(m[1]), mo=m[2]?Number(m[2]):1, d=m[3]?Number(m[3]):1;
  if(mo<1||mo>12||d<1||d>31) return null;
  return { y:y, m:mo, d:d, key:y*10000+mo*100+d, label:m[1]+(m[2]?'-'+(mo<10?'0':'')+mo:'')+(m[3]?'-'+(d<10?'0':'')+d:'') };
}
function tmlParse(text){
  var events=[], lines=String(text||'').split('\n');
  for(var i=0;i<lines.length;i++){
    var ln=lines[i].trim();
    if(!ln || ln.charAt(0)==='#') continue;
    var parts=ln.split('|').map(function(p){ return p.trim(); });
    if(parts.length<2) return { error:'第 '+(i+1)+' 行缺少「日期 | 标题」' };
    var dt=tmlParseDate(parts[0]);
    if(!dt) return { error:'第 '+(i+1)+' 行日期非法（YYYY[-MM[-DD]]）' };
    if(!parts[1]) return { error:'第 '+(i+1)+' 行标题为空' };
    events.push({ date:dt, title:parts[1], desc:parts[2]||'' });
  }
  if(!events.length) return { error:'没有可用事件' };
  return { error:null, events:events };
}
function tmlSort(events){
  return events.slice().sort(function(a,b){ return a.date.key-b.date.key; });
}
function tmlEsc(s){ return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function tmlSvg(events){
  var ev=tmlSort(events);
  var ROW=86, W=680, CX=W/2, PAD=30;
  var H=PAD*2+ev.length*ROW;
  var cols=['#5E6AD2','#22D3EE','#10B981','#A78BFA','#F5A623'];
  var s='<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" viewBox="0 0 '+W+' '+H+'">';
  s+='<rect width="'+W+'" height="'+H+'" fill="#0A0A0B"/>';
  s+='<line x1="'+CX+'" y1="'+PAD+'" x2="'+CX+'" y2="'+(H-PAD)+'" stroke="rgba(255,255,255,.15)" stroke-width="2"/>';
  for(var i=0;i<ev.length;i++){
    var y=PAD+i*ROW+ROW/2, left=(i%2===0), c=cols[i%cols.length];
    var bx=left ? CX-320 : CX+40, tx=bx+14, anchor='start';
    s+='<circle cx="'+CX+'" cy="'+y+'" r="7" fill="'+c+'" stroke="#0A0A0B" stroke-width="2"/>';
    s+='<line x1="'+(left?CX-40:CX+7)+'" y1="'+y+'" x2="'+(left?CX-7:CX+40)+'" y2="'+y+'" stroke="'+c+'" stroke-width="1.5"/>';
    s+='<rect x="'+bx+'" y="'+(y-30)+'" width="280" height="60" rx="10" fill="#141417" stroke="rgba(255,255,255,.08)"/>';
    s+='<text x="'+tx+'" y="'+(y-9)+'" font-family="system-ui,sans-serif" font-size="12" fill="'+c+'" text-anchor="'+anchor+'">'+tmlEsc(ev[i].date.label)+'</text>';
    s+='<text x="'+tx+'" y="'+(y+9)+'" font-family="system-ui,sans-serif" font-size="14" font-weight="600" fill="#FFFFFF" text-anchor="'+anchor+'">'+tmlEsc(ev[i].title)+'</text>';
    if(ev[i].desc) s+='<text x="'+tx+'" y="'+(y+24)+'" font-family="system-ui,sans-serif" font-size="11" fill="#A1A1AA" text-anchor="'+anchor+'">'+tmlEsc(ev[i].desc.slice(0,34))+'</text>';
  }
  return s+'</svg>';
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { tmlParseDate:tmlParseDate, tmlParse:tmlParse, tmlSort:tmlSort, tmlSvg:tmlSvg, tmlEsc:tmlEsc };
}
if (typeof window !== 'undefined') {
